 "kontakter": [{"name": "John Leonard Settergren", "role_title": "ägare", "phone": "070-145 22 40", "kontaktytor": ["avtalskontakt"], "bra_att_veta": "Källa: Kontaktuppgifter switch – Telia alla kunder (nov 2026)"}, {"name": "Info (allmän e-post)", "role_title": "Allmän e-post", "email": "info@settergrensfastigheter.se", "kontaktytor": ["infomail"], "bra_att_veta": "Källa: Kontaktuppgifter switch – Telia alla kunder (nov 2026)"}]}, {"part": "Söderfast", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Söderfast AB"}], "kontakter": []}, {"part": "Alania", "vaxel": "0300-56 49 00", "mal": [{"typ": "koncernmoder", "titel": "Alania Fastighets AB"}], "kontakter": []}, {"part": "J.N. von Bergen & Son AB", "vaxel": "0708129919 / 0708329121", "mal": [{"typ": "koncernmoder", "titel": "J.N.VON Bergen & Son AB"}, {"typ": "koncernmoder", "titel": "J.N.VON BERGEN&SON AB"}], "kontakter": []}, {"part": "Tribo Fastigheter", "vaxel": "0910 - 77 53 30", "mal": [{"typ": "koncernmoder", "titel": "TRIBO FASTIGHETER AB"}], "kontakter": []}, {"part": "Shamoun", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "SHAMOUN Invest AB"}], "kontakter": []}, {"part": "Meras Holding", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Meras Holding AB"}], "kontakter": []}, {"part": "Hans Lundbäck fastigheter", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Hans Lundbäck Fastigheter AB"}], "kontakter": []}, {"part": "Centria", "vaxel": "013-25 36 60", "mal": [{"typ": "koncernmoder", "titel": "Centria fastigheter"}], "kontakter": []}, {"part": "Vasaparken", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Vasaparken Absalon AB"}], "kontakter": []}, {"part": "3xJ Holding AB", "vaxel": "013-24 20 30", "mal": [{"typ": "koncernmoder", "titel": "3xJ Holding AB"}], "kontakter": []}, {"part": "Grensell Holding AB", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Grensell Holding AB"}], "kontakter": []}, {"part": "Slagstahuset Fastighets AB", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Slagstahuset Fastighets AB"}], "kontakter": []}, {"part": "Carl Dahlberg Fastigheter AB", "vaxel": "031-47 21 27", "mal": [{"typ": "koncernmoder", "titel": "Carl Dahlberg Fastighetsförvaltning Aktiebolag"}], "kontakter": []}, {"part": "Wallsten Företagen", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "Wallsténföretagen Aktiebolag"}], "kontakter": []}, {"part": "Hartwig Wennberg", "vaxel": null, "mal": [{"typ": "koncernmoder", "titel": "HARTWIG WENNBERG"}], "kontakter": []}, {"part": "Solbacka / Agona", "vaxel": "0480-100 79", "mal": [{"typ": "koncernmoder", "titel": "Agona Fastigheter Aktiebolag"}], "kontakter": []}]$j$::jsonb;
begin
  for v_t in select id from tenants loop
    for rad in select * from jsonb_array_elements(v_data) loop
      select array_agg(r.id) into v_mal
        from jsonb_array_elements(rad->'mal') m2
        join records r on r.tenant_id = v_t and r.deleted_at is null
                      and r.object_type = m2->>'typ' and r.title = m2->>'titel';
      continue when v_mal is null;

      -- Växelnummer på bolaget om det saknas.
      if coalesce(rad->>'vaxel', '') <> '' then
        update records set data = data || jsonb_build_object('vaxelnummer', rad->>'vaxel')
         where id = any(v_mal) and object_type = 'koncernmoder' and coalesce(data->>'vaxelnummer', '') = '';
        update records set data = data || jsonb_build_object('phone', rad->>'vaxel')
         where id = any(v_mal) and object_type = 'direktagt_bolag' and coalesce(data->>'phone', '') = '';
      end if;

      for k in select * from jsonb_array_elements(rad->'kontakter') loop
        select c.id into v_c
          from records c join relationships r on r.from_record_id = c.id
                        and r.rel_type in ('contact_of', 'contact_of_db', 'contact_of_fb') and r.to_record_id = any(v_mal)
         where c.tenant_id = v_t and c.object_type = 'contact' and c.deleted_at is null
           and lower(c.data->>'name') = lower(k->>'name')
         limit 1;
        if v_c is null then
          insert into records (tenant_id, object_type, data)
          values (v_t, 'contact', k) returning id into v_c;
          v_nya := v_nya + 1;
        end if;
        for v_b in select id, object_type from records where id = any(v_mal) loop
          insert into relationships (tenant_id, from_record_id, to_record_id, rel_type)
          select v_t, v_c, v_b.id, case v_b.object_type when 'koncernmoder' then 'contact_of' else 'contact_of_db' end
           where not exists (select 1 from relationships x where x.from_record_id = v_c and x.to_record_id = v_b.id
                              and x.rel_type in ('contact_of', 'contact_of_db'));
          get diagnostics v_n = row_count; v_rel := v_rel + v_n;
        end loop;
      end loop;
    end loop;
  end loop;
  raise notice 'Kontakter: % nya, % kopplingar', v_nya, v_rel;
end $$;
